def load() -> pd.DataFrame:
    import glob
    all_data = []
    files = glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Fraud and Other data/*.csv')

    for filepath in files:
        try:
            df = pd.read_csv(filepath, skiprows=2)
            df = df.dropna(subset=['Metropolitan Area'])
            df = df[df['Metropolitan Area'].str.strip() != '']
            df = df[~df['Metropolitan Area'].str.contains('Metropolitan Areas are defined|Source:', na=False)]
            if len(df) > 0:
                state = filepath.split('/')[-1].replace('.csv', '')
                df['State'] = state
                all_data.append(df)
        except Exception as e:
            continue

    if all_data:
        result = pd.concat(all_data, ignore_index=True)
        return result
    else:
        return pd.DataFrame()

def process(clean_reports) -> pd.DataFrame:
